            "halfVectorResizingFromHalfDouble through GenericAnySourcePair<Int8, Double>"
        )
        let aInputs = Inputs.conversions(SIMD<Double>.HalfVector.self, seed: 0x86DB_ED15_78F6_A0EE)
            .map(poisoningUpperBytes)
        for a in aInputs {
            let port = GenericAnySourcePair<Int8, Double>.halfVector(resizing: a)
            let reference = H.halfVector(resizing: a)
            let definedBytes = SIMD<Double>.HalfVector.laneCount * MemoryLayout<Double>.stride
            let grownBytes = H.HalfVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                MemoryLayout<SIMD<Double>.HalfVector.Raw>.size
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

